collect($page->outgoingLinks ?? [])
            ->sortByDesc('priority')
            ->map(function ($link, int $index) {
                $target = $link->targetPage;

                if (! $target) {
                    return null;
                }

                return [
                    '@type' => 'ListItem',
                    'position' => $index + 1,
                    'url' => $target->canonical_url ?: url('/seo-pages/'.$target->slug),
                    'name' => $link->anchor_text ?: ($target->h1 ?: $target->title ?: $target->primary_keyword),
                ];
            })
            ->filter()
            ->take(8)
            ->values()->all

